parameters.jsCode:
const servicios = $input.all();

const catalogo = servicios.map(s => {
  const f = s.json.fields;
  return `- ${f['Nombre servicio']} | ${f['Descripción']} | Precio: ${f['Rango de precio']} | Plazo: ${f['Plazo típico']}`;
}).join('\n');

return [{
  json: {
    catalogo_servicios: catalogo,
    servicios_raw: servicios.map(s => ({
      id: s.json.id,
      nombre: s.json.fields['Nombre servicio'],
      descripcion: s.json.fields['Descripción'],
      precio: s.json.fields['Rango de precio'],
      plazo: s.json.fields['Plazo típico']
    }))
  }
}];

