parameters.jsCode:
const raw = $input.first().json.content[0].text;
const limpio = raw.replace(/```json|```/g, '').trim();

let datos;
try {
  datos = JSON.parse(limpio);
} catch (e) {
  throw new Error('La IA no devolvió JSON válido: ' + limpio.substring(0, 200));
}

const servicios = $('Formatear catálogo').first().json.servicios_raw;
const match = servicios.find(s => s.nombre === datos.servicio);

return [{
  json: {
    ...datos,
    servicio_id: match ? match.id : null,
    descripcion_servicio: match ? match.descripcion : null,
    rango_precio: match ? match.precio : null,
    plazo_tipico: match ? match.plazo : null
  }
}];

